"""장바구니."""
from .pricing import apply_discount


class Cart:
    def __init__(self):
        self.items = []  # (sku, unit_price_cents, qty)

    def add(self, sku: str, unit_price_cents: int, qty: int = 1) -> None:
        self.items.append((sku, unit_price_cents, qty))

    def subtotal(self) -> int:
        """수량을 곱한 합계(센트)."""
        return sum(price for _, price, _ in self.items)

    def total(self, discount_percent: int = 0) -> int:
        return apply_discount(self.subtotal(), discount_percent)
